  ('camouflage-paint-kit-nb', 'Camouflage Paint Kit', 'nightbane', 'gear', NULL, 35, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, '4 spray cans plus 6 stencils for easy camouflaging of vehicles, bunkers and any field equipment. One kit covers approximately 100 square feet of surface. Available in jungle, forest or arctic.', 'Nightbane RPG p.228');
INSERT INTO gear (slug, name, system, category, weight_lbs, cost, cost_note, damage, is_mega_damage, range, payload, rate_of_fire, ar, sdc, description, source_book)
VALUES
  ('camouflage-tape-nb', 'Camouflage Tape', 'nightbane', 'gear', NULL, 6, '$6.00 per roll', NULL, 0, NULL, NULL, NULL, NULL, NULL, 'The ever popular duct tape, in rolls 26ft long and two inches wide. Available in jungle, forest or desert camouflage, or in olive drab.', 'Nightbane RPG p.228'),
  ('camouflage-compact-nb', 'Camouflage Compact', 'nightbane', 'gear', NULL, 18, '$18.00 each', NULL, 0, NULL, NULL, NULL, NULL, NULL, 'A one-man kit for camouflage or night operations with enough face and hand paint for 6 applications. Mirror, brush and disposable cleaning pads are included in a neat black case 4 inches in diameter and half an inch high.', 'Nightbane RPG p.228'),
  ('climbing-kit-nb', 'Climbing Kit', 'nightbane', 'gear', NULL, 1100, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, 'A complete set of equipment for rappelling, rock scaling or climbing: 3,600ft reels of 4500 test rope (each reel weighs 40lbs), an adjustable harness with clamps, 6 pairs of canvas climbing gloves, 48 clamps, 48 fasteners, 48 pitons, 3 hammers, 2 grappling hooks and one pulley. Weight with shipping crate is 190lbs.', 'Nightbane RPG p.228'),
  ('ear-protector-headphones-nb', 'Ear Protector Headphones', 'nightbane', 'gear', NULL, 35, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, 'The answer to the Demo expert''s and grenadier''s dreams. The same model is used by airport workers to preserve hearing in noisy environments.', 'Nightbane RPG p.228'),
  ('electro-adhesive-pads-and-generator-nb', 'Electro-Adhesive Pads and Generator', 'nightbane', 'gear', NULL, 40000, '$40,000 for the two pads and the hip or back-pack generator; not commonly available', NULL, 0, NULL, NULL, NULL, NULL, NULL, 'A hand-held device that adheres strongly to any metal surface by passing a small current through two metal electrodes. These pads are commonly used by astronauts and can be used in astronauts'' shoes, but the hand-held pads are much more flexible and generally preferred. Two pads plus a hip or back-pack generator. Can hold up to 1000lbs; works ONLY on metal.', 'Nightbane RPG p.228'),
  ('electro-adhesive-shoes-nb', 'Electro-Adhesive Shoes', 'nightbane', 'gear', NULL, 50000, '$50,000; not commonly available', NULL, 0, NULL, NULL, NULL, NULL, NULL, 'The shoe form of the Electro-Adhesive Pad, priced separately in the same entry on printed 228. Can hold up to 1000lbs; works only on metal.', 'Nightbane RPG p.228'),
  ('flashlight-small-nb', 'Flashlight - Small', 'nightbane', 'gear', NULL, 5, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, 'Miscellaneous equipment price list, printed 228.', 'Nightbane RPG p.228'),
  ('flashlight-medium-nb', 'Flashlight - Medium', 'nightbane', 'gear', NULL, 10, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, 'Miscellaneous equipment price list, printed 228.', 'Nightbane RPG p.228'),
  ('flashlight-large-nb', 'Flashlight - Large', 'nightbane', 'gear', NULL, 15, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, 'Miscellaneous equipment price list, printed 228.', 'Nightbane RPG p.228'),
  ('flashlight-unbreakable-kel-lite-small-nb', 'Flashlight - Unbreakable (Kel-lite), Small', 'nightbane', 'gear', NULL, 24, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, 'Miscellaneous equipment price list, printed 228.', 'Nightbane RPG p.228'),
  ('flashlight-unbreakable-kel-lite-medium-nb', 'Flashlight - Unbreakable (Kel-lite), Medium', 'nightbane', 'gear', NULL, 28, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, 'Miscellaneous equipment price list, printed 228.', 'Nightbane RPG p.228'),
  ('flashlight-unbreakable-kel-lite-large-nb', 'Flashlight - Unbreakable (Kel-lite), Large', 'nightbane', 'gear', NULL, 32, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, 'Miscellaneous equipment price list, printed 228.', 'Nightbane RPG p.228'),
  ('flashlight-unbreakable-kel-lite-very-large-nb', 'Flashlight - Unbreakable (Kel-lite), Very Large', 'nightbane', 'gear', NULL, 35, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, 'Miscellaneous equipment price list, printed 228.', 'Nightbane RPG p.228'),
  ('rechargeable-unbreakable-flashlight-20-000-candle-power-nb', 'Rechargeable Unbreakable Flashlight (20,000 candle power)', 'nightbane', 'gear', NULL, 130, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, '10 times brighter than most conventional types; quartz-halogen bulb, 12 inches (0.3m), 1.8lbs, 20,000 candle power.', 'Nightbane RPG p.228'),
  ('rechargeable-unbreakable-flashlight-35-000-candle-power-nb', 'Rechargeable Unbreakable Flashlight (35,000 candle power)', 'nightbane', 'gear', NULL, 160, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, 'The 35,000 candle power version of the rechargeable unbreakable flashlight, priced separately in the same entry on printed 228.', 'Nightbane RPG p.228'),
  ('portable-halogen-spotlight-nb', 'Portable Halogen Spotlight', 'nightbane', 'gear', NULL, 30, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, '50,000 candle power.', 'Nightbane RPG p.228'),
  ('treated-torch-nb', 'Treated Torch', 'nightbane', 'gear', NULL, 8, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, 'Miscellaneous equipment price list, printed 228.', 'Nightbane RPG p.228'),
  ('candle-stick-per-dozen-nb', 'Candle Stick - Per Dozen', 'nightbane', 'gear', NULL, 8, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, 'Miscellaneous equipment price list, printed 228.', 'Nightbane RPG p.228'),
  ('oil-lantern-6-hours-1-pint-nb', 'Oil Lantern - 6 hours/1 pint', 'nightbane', 'gear', NULL, 20, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, 'Miscellaneous equipment price list, printed 228.', 'Nightbane RPG p.228'),
  ('oil-lantern-12-hours-2-pints-nb', 'Oil Lantern - 12 hours/2 pints', 'nightbane', 'gear', NULL, 30, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, 'Miscellaneous equipment price list, printed 228.', 'Nightbane RPG p.228'),
  ('oil-lamp-6-hours-nb', 'Oil Lamp - 6 hours', 'nightbane', 'gear', NULL, 30, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, 'Miscellaneous equipment price list, printed 228.', 'Nightbane RPG p.228'),
  ('padlock-light-nb', 'Padlock - Light', 'nightbane', 'gear', NULL, 5, NULL, NULL, 0, NULL, NULL, NULL, NULL, 25, 'Miscellaneous equipment price list, printed 228.', 'Nightbane RPG p.228'),
  ('padlock-medium-nb', 'Padlock - Medium', 'nightbane', 'gear', NULL, 8, NULL, NULL, 0, NULL, NULL, NULL, NULL, 50, 'Miscellaneous equipment price list, printed 228.', 'Nightbane RPG p.228'),
  ('padlock-heavy-nb', 'Padlock - Heavy', 'nightbane', 'gear', NULL, 15, NULL, NULL, 0, NULL, NULL, NULL, NULL, 75, 'Miscellaneous equipment price list, printed 228.', 'Nightbane RPG p.228'),
  ('padlock-burglar-proof-nb', 'Padlock - Burglar proof', 'nightbane', 'gear', NULL, 30, NULL, NULL, 0, NULL, NULL, NULL, NULL, 80, '60% chance to be picked.', 'Nightbane RPG p.228'),
  ('handcuffs-regular-nb', 'Handcuffs - Regular', 'nightbane', 'gear', NULL, 25, NULL, NULL, 0, NULL, NULL, NULL, NULL, 60, 'Miscellaneous equipment price list, printed 228.', 'Nightbane RPG p.228'),
  ('handcuffs-heavy-nb', 'Handcuffs - Heavy', 'nightbane', 'gear', NULL, 50, NULL, NULL, 0, NULL, NULL, NULL, NULL, 120, 'Miscellaneous equipment price list, printed 228.', 'Nightbane RPG p.228'),
  ('medical-bag-nb', 'Medical Bag', 'nightbane', 'gear', NULL, 275, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, 'An 8lb complete Medic''s field kit: adhesive pads, bandages, gauze pads, adhesive tape, splints, sterile gloves, scissors, forceps, thermometer, needle, razor blades, pins, medicine, ointment and salt tablets. Back pack and shoulder straps; available in camouflage, green or khaki.', 'Nightbane RPG p.228'),
  ('professional-medical-kit-nb', 'Professional Medical Kit', 'nightbane', 'gear', NULL, 200, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, 'A comprehensive first aid kit with six doses each of antibiotics, anti-inflammatories, sedatives and painkillers; an assorted mini-instrument pack with scalpels, scissors, probes, etc., a dozen in all; tape, bandages, sutures and four air filters.', 'Nightbane RPG p.228'),
  ('professional-medical-kit-open-market-without-drugs-nb', 'Professional Medical Kit (open market, without drugs)', 'nightbane', 'gear', NULL, 1500, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, 'The same kit WITHOUT the drugs, which is the form printed 228 says is available on the open market, at a cost of $1500.', 'Nightbane RPG p.228'),
  ('machete-nb', 'Machete', 'nightbane', 'gear', NULL, 30, NULL, '1D6', 0, NULL, NULL, NULL, NULL, NULL, 'Complete with canvas sheath.', 'Nightbane RPG p.228'),
  ('wirecutters-nb', 'Wirecutters', 'nightbane', 'gear', NULL, 65, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, '8 inch wirecutter with nonconducting handles to avoid the nasty "shock" of electrified fences. Complete with belt sheath.', 'Nightbane RPG p.228'),
  ('rations-nb', 'Rations', 'nightbane', 'gear', 200, 470, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, 'Dry field rations; each 15lb case includes 12 meals. A crate is stocked with 12 cases and has a total shipping weight of 200lbs.', 'Nightbane RPG p.229'),
  ('food-ration-packs-nb', 'Food Ration Packs', 'nightbane', 'gear', NULL, 2000, '$2000. Limited availability', NULL, 0, NULL, NULL, NULL, NULL, NULL, 'A food pack of concentrated, vitamin enriched, freeze-dried rations, enough to easily last two weeks; can be stretched to last four weeks if necessary. Geared for two-man consumption.', 'Nightbane RPG p.229'),
  ('padded-helmet-nb', 'Padded Helmet', 'nightbane', 'gear', NULL, 25, '$25 to $75', NULL, 0, NULL, NULL, NULL, 10, NULL, 'A padded helmet, A.R. 10.', 'Nightbane RPG p.229'),
  ('protective-goggles-or-tinted-visor-nb', 'Protective Goggles or Tinted Visor', 'nightbane', 'gear', NULL, 20, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, 'Designed for use outdoors or for welding. Unbreakable plastic lenses. Printed 229 ALSO lists a plain Protective Goggles at $10.00 in the price lines a few entries later; both are rows, each as printed.', 'Nightbane RPG p.229'),
  ('face-protector-and-gas-mask-nb', 'Face Protector and Gas Mask', 'nightbane', 'gear', NULL, 200, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, 'The mask can attach to most standard helmets, providing added protection to the face and eyes. Tinted visor and detachable air filter are standard.', 'Nightbane RPG p.229'),
  ('face-protector-and-gas-mask-with-independent-oxygen-nb', 'Face Protector and Gas Mask with Independent Oxygen', 'nightbane', 'gear', NULL, 600, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, 'The same mask with gas mask modification and an independent oxygen supply (2 hours), priced in the same entry on printed 229.', 'Nightbane RPG p.229'),
  ('conventional-air-filter-nb', 'Conventional Air Filter', 'nightbane', 'gear', NULL, 75, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, 'Fits over nose and mouth.', 'Nightbane RPG p.229'),
  ('conventional-gas-mask-nb', 'Conventional Gas Mask', 'nightbane', 'gear', NULL, 100, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, 'With a superior filtering system.', 'Nightbane RPG p.229');
