  ('jet-pack-nb', 'Jet Pack', 'nightbane', 'gear', NULL, 80000, '$80,000.00, plus $500.00 per tank of fuel - one tank is the 40 minute flight capacity', NULL, 0, NULL, NULL, NULL, NULL, 100, 'Speed: 80mph maximum. Duration of flight: 40 minutes maximum. Maximum height: 300ft. Jet Pack S.D.C.: 100.', 'Nightbane RPG p.229'),
  ('space-suit-nb', 'Space Suit', 'nightbane', 'gear', NULL, 250000, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, 'Complete: a self-contained environmental suit, insulated, heat and cold shielded, oxygen and life support system; the whole works.', 'Nightbane RPG p.229'),
  ('organic-acid-nb', 'Organic Acid', 'nightbane', 'gear', NULL, 75, '$75.00 per half gallon. The cost line calls this one Organic I', '2-12 per melee for four melees', 0, NULL, NULL, NULL, NULL, NULL, 'Affects only organic substances. All acids are not common household items and must be acquired from a chemical supplier, industry or an illegal outlet. From a supplier or industry, large bulk orders may be required; from an illegal outlet availability is extremely low (9% chance of getting the item) and the cost is multiplied ten times.', 'Nightbane RPG p.229'),
  ('organic-acid-concentrated-nb', 'Organic Acid (concentrated)', 'nightbane', 'gear', NULL, 120, '$120.00 per half gallon. The cost line calls this one Organic II', '4-24 per melee for four melees', 0, NULL, NULL, NULL, NULL, NULL, 'The concentrated form; affects organic substances. All acids are not common household items and must be acquired from a chemical supplier, industry or an illegal outlet. From a supplier or industry, large bulk orders may be required; from an illegal outlet availability is extremely low (9% chance of getting the item) and the cost is multiplied ten times.', 'Nightbane RPG p.229'),
  ('cleanser-nb', 'Cleanser', 'nightbane', 'gear', NULL, 180, '$180.00 per half gallon', '2-12 to organic, 1-6 to all other substances', 0, NULL, NULL, NULL, NULL, NULL, 'Does 2-12 damage to organic and 1-6 damage to all other substances. All acids are not common household items and must be acquired from a chemical supplier, industry or an illegal outlet. From a supplier or industry, large bulk orders may be required; from an illegal outlet availability is extremely low (9% chance of getting the item) and the cost is multiplied ten times.', 'Nightbane RPG p.229'),
  ('metal-dissolver-nb', 'Metal Dissolver', 'nightbane', 'gear', NULL, 600, '$600.00 per half gallon', '4-24 per melee for four melees, 1-8 per melee to organics and plastics', 0, NULL, NULL, NULL, NULL, NULL, 'Industrial. All acids are not common household items and must be acquired from a chemical supplier, industry or an illegal outlet. From a supplier or industry, large bulk orders may be required; from an illegal outlet availability is extremely low (9% chance of getting the item) and the cost is multiplied ten times.', 'Nightbane RPG p.229'),
  ('nylon-cord-nb', 'Nylon Cord', 'nightbane', 'gear', NULL, 100, 'about $100. Good availability', NULL, 0, NULL, NULL, NULL, NULL, NULL, 'A variety of heavy-duty, all-purpose nylon rope or cord. Average tension strength is 600lbs (270kg); average length is 300ft (90m).', 'Nightbane RPG p.229'),
  ('police-style-jumpsuit-nb', 'Police Style Jumpsuit', 'nightbane', 'gear', NULL, 80, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, 'One-piece, zippers down the middle; large zippered chest pockets (2), front pockets (2), rear pockets (2), pencil/pen slot (left arm), sleeves and leg cuffs zipper for adjustability, bi-swing pleated back, and padded knees.', 'Nightbane RPG p.229'),
  ('heavy-camouflage-coveralls-tiger-stripe-camouflage-nb', 'Heavy Camouflage Coveralls - Tiger Stripe Camouflage', 'nightbane', 'gear', NULL, 80, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, 'Heavy Camouflage Coveralls (jumpsuit style): insulated lining for cold weather (above freezing level cold), wrist and ankle elastic for tight fit, 6 pockets (chest, hip, rear). Combat/hunting clothing, printed 229.', 'Nightbane RPG p.229'),
  ('heavy-camouflage-coveralls-tree-bark-camouflage-nb', 'Heavy Camouflage Coveralls - Tree Bark Camouflage', 'nightbane', 'gear', NULL, 85, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, 'Heavy Camouflage Coveralls (jumpsuit style): insulated lining for cold weather (above freezing level cold), wrist and ankle elastic for tight fit, 6 pockets (chest, hip, rear). Combat/hunting clothing, printed 229.', 'Nightbane RPG p.229'),
  ('heavy-camouflage-coveralls-black-or-white-nb', 'Heavy Camouflage Coveralls - Black or White', 'nightbane', 'gear', NULL, 75, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, 'Heavy Camouflage Coveralls (jumpsuit style): insulated lining for cold weather (above freezing level cold), wrist and ankle elastic for tight fit, 6 pockets (chest, hip, rear). Combat/hunting clothing, printed 229.', 'Nightbane RPG p.229'),
  ('heavy-camouflage-coveralls-green-nb', 'Heavy Camouflage Coveralls - Green', 'nightbane', 'gear', NULL, 75, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, 'Heavy Camouflage Coveralls (jumpsuit style): insulated lining for cold weather (above freezing level cold), wrist and ankle elastic for tight fit, 6 pockets (chest, hip, rear). Combat/hunting clothing, printed 229.', 'Nightbane RPG p.229'),
  ('light-camouflage-coveralls-tiger-stripe-camouflage-nb', 'Light Camouflage Coveralls - Tiger Stripe Camouflage', 'nightbane', 'gear', NULL, 50, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, 'Light Camouflage Coveralls (jumpsuit style): cotton and polyester blend. Combat/hunting clothing, printed 229.', 'Nightbane RPG p.229'),
  ('light-camouflage-coveralls-tree-bark-camouflage-nb', 'Light Camouflage Coveralls - Tree Bark Camouflage', 'nightbane', 'gear', NULL, 60, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, 'Light Camouflage Coveralls (jumpsuit style): cotton and polyester blend. Combat/hunting clothing, printed 229.', 'Nightbane RPG p.229'),
  ('light-camouflage-coveralls-black-or-white-nb', 'Light Camouflage Coveralls - Black or White', 'nightbane', 'gear', NULL, 45, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, 'Light Camouflage Coveralls (jumpsuit style): cotton and polyester blend. Combat/hunting clothing, printed 229.', 'Nightbane RPG p.229'),
  ('light-camouflage-coveralls-green-nb', 'Light Camouflage Coveralls - Green', 'nightbane', 'gear', NULL, 45, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, 'Light Camouflage Coveralls (jumpsuit style): cotton and polyester blend. Combat/hunting clothing, printed 229.', 'Nightbane RPG p.229'),
  ('3-d-camouflage-suit-nb', '3-D Camouflage Suit', 'nightbane', 'gear', NULL, 150, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, 'A multi-shade of drab green and brown, with approximately 250 individual hanging strips to blend into the foliage. Bonus: +10% on prowl skill when in woodland environment.', 'Nightbane RPG p.229'),
  ('below-30-degree-coveralls-nb', 'Below 30 Degree Coveralls', 'nightbane', 'gear', NULL, 80, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, 'Insulated for prolonged exposure in the extreme cold, with thick turtleneck collar that covers chin, nose and mouth. The outer fabric is an acid resistant cotton/polyester twill; zippers at leg bottoms for easy removal; knit, windproof cuffs; sleeve pockets (one each arm) and six large pockets. Comes with zip-off hood. Suitable for up to 20 degrees below zero Fahrenheit.', 'Nightbane RPG p.229'),
  ('work-overalls-nb', 'Work Overalls', 'nightbane', 'gear', NULL, 40, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, 'Jumpsuit style.', 'Nightbane RPG p.229'),
  ('expendable-lab-coat-or-coveralls-nb', 'Expendable Lab Coat or Coveralls', 'nightbane', 'gear', NULL, 6, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, 'Made from a special non-woven fabric that is acid, grease and lint resistant. Can be worn once or a dozen times, then thrown away.', 'Nightbane RPG p.229'),
  ('battle-dress-uniform-fatigues-pants-tiger-stripe-camouflage-nb', 'Battle Dress Uniform (Fatigues) - Pants - Tiger Stripe Camouflage', 'nightbane', 'gear', NULL, 30, 'Pants: 6 pockets, adjustable waist tab, button fly, drawstring cuffs', NULL, 0, NULL, NULL, NULL, NULL, NULL, 'Battle Dress Uniform (Fatigues) pants: 6 pockets, adjustable waist tab, button fly, drawstring cuffs. Combat/hunting clothing, printed 229.', 'Nightbane RPG p.229'),
  ('battle-dress-uniform-fatigues-pants-tree-bark-camouflage-nb', 'Battle Dress Uniform (Fatigues) - Pants - Tree Bark Camouflage', 'nightbane', 'gear', NULL, 35, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, 'Battle Dress Uniform (Fatigues) pants: 6 pockets, adjustable waist tab, button fly, drawstring cuffs. Combat/hunting clothing; the pants list begins on printed 229 and continues on 230.', 'Nightbane RPG p.230');
