  ('military-field-jacket-nb', 'Military Field Jacket', 'nightbane', 'gear', NULL, 60, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, 'Includes adjustable collar and cuffs, epaulets, 4 large outer pockets with heavy brass zippers, hidden hood, waist cord and snap closures.', 'Nightbane RPG p.230'),
  ('reversible-flight-jacket-light-nb', 'Reversible Flight Jacket - Light', 'nightbane', 'gear', NULL, 50, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, 'Comes in navy blue, grey, green and brown.', 'Nightbane RPG p.230'),
  ('extreme-cold-weather-flight-jacket-nb', 'Extreme Cold Weather Flight Jacket', 'nightbane', 'gear', NULL, 100, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, 'Heavy, insulated. Comes in navy blue, grey, green, brown and white.', 'Nightbane RPG p.230'),
  ('battle-dress-utility-lightweight-nb', 'Battle Dress Utility - Lightweight', 'nightbane', 'gear', NULL, 65, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, 'Shirt and pants in choice of arctic, desert, jungle or autumn forest camouflage. The shirt has two breast pockets, one pen pocket and one (left-side) interior pocket; the pants have hip, butt and thigh pockets. Lightweight is for desert and jungle.', 'Nightbane RPG p.230'),
  ('battle-dress-utility-medium-weight-nb', 'Battle Dress Utility - Medium Weight', 'nightbane', 'gear', NULL, 90, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, 'The same Battle Dress Utility shirt and pants in medium weight, for forest and mountain; priced in the same entry on printed 230.', 'Nightbane RPG p.230'),
  ('battle-dress-utility-arctic-weight-nb', 'Battle Dress Utility - Arctic Weight', 'nightbane', 'gear', NULL, 365, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, 'The same Battle Dress Utility shirt and pants in arctic weight (down lined); priced in the same entry on printed 230.', 'Nightbane RPG p.230'),
  ('battle-jacket-nb', 'Battle Jacket', 'nightbane', 'gear', NULL, 225, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, 'Comes equipped with breast, hip and interior pockets on both sides. A hidden pocket on the inside of the back is also useful. Available in camouflage, khaki, green or black.', 'Nightbane RPG p.230'),
  ('arctic-parka-nb', 'Arctic Parka', 'nightbane', 'gear', NULL, 450, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, 'High quality down lining provides protection in sub-zero conditions. Same pocket arrangement as Battle Jacket. Available in green and white only.', 'Nightbane RPG p.230'),
  ('wool-sweaters-nb', 'Wool Sweaters', 'nightbane', 'gear', NULL, 150, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, 'Finest British quality knit with leather reinforcements at shoulders, elbows and neck. Available in cream, green or black.', 'Nightbane RPG p.230'),
  ('ponchos-nb', 'Ponchos', 'nightbane', 'gear', NULL, 35, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, 'Waterproof nylon. Useful for rain protection, ground cover, emergency tent, etc. 5ft by 5ft square. Available in camouflage. The general purpose list on the same page prints a separate Rain Poncho at $30.00.', 'Nightbane RPG p.230'),
  ('camouflage-t-shirt-nb', 'Camouflage T-Shirt', 'nightbane', 'gear', NULL, 8, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, 'Combat/hunting clothing, printed 230.', 'Nightbane RPG p.230'),
  ('khaki-bush-shorts-nb', 'Khaki Bush Shorts', 'nightbane', 'gear', NULL, 20, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, 'Combat/hunting clothing, printed 230.', 'Nightbane RPG p.230'),
  ('police-style-riot-helmet-nb', 'Police Style Riot Helmet', 'nightbane', 'gear', NULL, 60, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, 'With ventilated transparent face shield.', 'Nightbane RPG p.230'),
  ('combat-helmet-nb', 'Combat Helmet', 'nightbane', 'gear', NULL, 40, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, 'Complete with liner and camouflage cover.', 'Nightbane RPG p.230'),
  ('safari-hat-nb', 'Safari Hat', 'nightbane', 'gear', NULL, 125, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, 'A wide-brimmed hat perfect for shading the eyes in tropical sunlight and classy enough for an evening out on the town. Fasteners on each side for an easy ''Aussie style'' flip. Available in camouflage, cream, green or khaki.', 'Nightbane RPG p.230'),
  ('utility-cap-nb', 'Utility Cap', 'nightbane', 'gear', NULL, 14.5, '$14.50 - the only price on either page that is not a whole dollar', NULL, 0, NULL, NULL, NULL, NULL, NULL, 'A classic ''marine cover.'' Available in choice of camouflage, green or khaki.', 'Nightbane RPG p.230'),
  ('beret-nb', 'Beret', 'nightbane', 'gear', NULL, 20, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, 'The classic wool beret. Available in green, black, or jungle camouflage.', 'Nightbane RPG p.230'),
  ('bandanna-nb', 'Bandanna', 'nightbane', 'gear', NULL, 5, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, 'In choice of colors.', 'Nightbane RPG p.230'),
  ('head-net-nb', 'Head Net', 'nightbane', 'gear', NULL, 15, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, 'Covers hair and face, leaving only a slit for the eyes.', 'Nightbane RPG p.230'),
